namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const decimal DiscountCeiling = 10m;

    public decimal ApplyTo(LoyaltyTier tier, decimal subtotal)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5m,
            LoyaltyTier.Silver => 7m,
            LoyaltyTier.Gold => 9m,
        };

        var orderSizeBonus = subtotal switch
        {
            >= 200.00m => 3m,
            >= 50.00m => 1m,
            _ => 0m,
        };

        var effectiveRate = Math.Min(baseRate + orderSizeBonus, DiscountCeiling);

        var discount = Math.Floor(subtotal * effectiveRate) / 100m;

        return subtotal - discount;
    }
}
EOF

